from flask import Flask, jsonify, request

app = Flask(__name__)
buecher = {1: {"id": 1, "titel": "Faust"}}

@app.get("/api/v1/buecher")
def alle():
    return jsonify(list(buecher.values()))

@app.get("/api/v1/buecher/<int:bid>")
def eines(bid):
    if bid not in buecher:
        return {"error": "nicht gefunden"}, 404
    return buecher[bid]

@app.post("/api/v1/buecher")
def neu():
    daten = request.get_json()
    if not daten or "titel" not in daten:
        return {"error": "titel fehlt"}, 400
    bid = max(buecher, default=0) + 1
    buecher[bid] = {"id": bid,
                    "titel": daten["titel"]}
    return buecher[bid], 201

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=5000)

